-- pintopets_medications: tenant-scoped rows behind /medications (generated by `opsapi make:resource`).
-- Runs once, inside a transaction. Never edit it after it has been applied —
-- add a new migration file instead.
return function(schema, db)
    db.query([[
        CREATE TABLE IF NOT EXISTS pintopets_medications (
            id BIGSERIAL PRIMARY KEY,
            uuid UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
            namespace_id INTEGER NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
            pet_uuid UUID NOT NULL REFERENCES pintopets_pets(uuid) ON DELETE CASCADE,
            created_by_user_uuid UUID NOT NULL,
            name VARCHAR(255) NOT NULL,
            dose_as_prescribed VARCHAR(255) NOT NULL,
            frequency VARCHAR(255) NOT NULL,
            start_on DATE NOT NULL,
            end_on DATE,
            prescribed_by VARCHAR(255),
            reminders_enabled BOOLEAN,
            notes TEXT,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        )
    ]])
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_medications_namespace ON pintopets_medications (namespace_id, id DESC)")
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_medications_pet ON pintopets_medications (namespace_id, pet_uuid)")
end
